    @staticmethod
    def _load_baseline(run_dir: Any) -> dict[str, Any]:
        if not run_dir:
            return {}
        path = Path(str(run_dir)) / "opentwitter_baseline.json"
        if not path.exists():
            return {}
        try:
            payload = json.loads(path.read_text(encoding="utf-8"))
        except Exception:
            return {}
        return payload if isinstance(payload, dict) else {}

    @staticmethod
    def _latest_event(events: list[Mapping[str, Any]], event_type: str, fields: Mapping[str, Any]) -> Mapping[str, Any] | None:
        matches = [
            event for event in events
            if str(event.get("type") or "") == event_type
            and all(event.get(key) == value for key, value in fields.items())
        ]
        return max(matches, key=lambda item: int(item.get("seq") or 0)) if matches else None

    @staticmethod
    def _check(name: str, passed: bool, expected: Any, observed: Any, matched_ids: list[str]) -> dict[str, Any]:
        return {
            "name": name,
            "passed": bool(passed),
            "expected": expected,
            "observed": observed,
            "matched_object_ids": matched_ids,
            "failure_reason": None if passed else f"{name} did not match exact final-state and event requirements",
        }

    @staticmethod
    def _text_list(raw: Any) -> list[str]:
        return [str(value).strip() for value in raw] if isinstance(raw, list) else []

    @staticmethod
    def _slug(text: str) -> str:
        return "_".join(text.lower().replace(".", "").split())[:50]
